def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # --- Last rounds: exploit cooperative opponents, defend against defectors.
    if n >= 97:
        opp_c = sum(1 for a, b in history if b == 'C')
        if opp_c >= 70:
            return 'D'
        if opp_c <= 20:
            return 'D'
        return 'C'

    # Opponent defect/coop counts and recent window.
    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c

    recent = history[-8:]
    r_opp_c = sum(1 for a, b in recent if b == 'C')
    r_opp_d = len(recent) - r_opp_c

    # Persistent defector: defect, with rare probe to let them recover.
    if n >= 15 and opp_d >= n - 3:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Very cooperative, established mutual cooperation: keep cooperating.
    if n >= 10 and r_opp_d == 0:
        # Late-game gentle exploitation of very cooperative partners.
        if n >= 85 and opp_c * 100 >= n * 90 and rng.random() < 0.35:
            return 'D'
        return 'C'

    last_opp = history[-1][1]
    last_me = history[-1][0]

    # Immediate strong punishment for defection streaks.
    if r_opp_d >= 4:
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Single defection: retaliate once, then return to cooperation.
    if last_opp == 'D':
        # If we just retaliated and the prior coops were fine, re-open with C.
        if last_me == 'D':
            # Occasional short continued punishment against repeat offenders.
            if r_opp_d >= 3 and rng.random() < 0.6:
                return 'D'
            return 'C'
        # If opponent was mostly cooperating overall, forgive quickly.
        if opp_c * 100 >= n * 60:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # If a defection streak just ended and opponent now cooperates, restore cooperation.
    if n >= 2 and history[-2][1] == 'D' and last_opp == 'C':
        return 'C'

    # Sustained mutual cooperation: cooperate.
    if r_opp_c >= 7:
        return 'C'

    # Against moderate coop rates, cooperate but probe occasionally.
    if opp_c * 100 >= n * 55:
        if n >= 30 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mixed middle zone: lean cooperative to rebuild.
    if opp_c * 100 >= n * 35:
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Mostly defecting opponent: defect, rarely probe for recovery.
    if rng.random() < 0.08:
        return 'C'
    return 'D'
